function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 10000) return 'arr needs 1 to 10^4 values.';
  if (!arr.every(v => Number.isInteger(v) && v >= 0 && v <= 100000)) return 'Each value is between 0 and 10^5.';
  for (let i = 1; i < arr.length; i++) {
    if (arr[i - 1] > arr[i]) return 'arr must be sorted in non-decreasing order.';
  }
  let frequent = 0;
  for (let i = 0, j = 0; i < arr.length; i = j) {
    while (j < arr.length && arr[j] === arr[i]) j++;
    if ((j - i) * 4 > arr.length) frequent++;
  }
  if (frequent !== 1) return 'Exactly one value must appear more than arr.length / 4 times.';
  return null;
}

