function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 16);
  const top = large ? 100000 : 20;
  const quarter = Math.floor(n / 4);
  // The special value needs more than n / 4 copies; every other value gets at most n / 4.
  const special = quarter === 0 ? n : quarter + 1 + Math.floor(rand() * (rand() < 0.5 ? 2 : n - quarter));
  const used = new Set();
  const fresh = () => {
    for (;;) {
      const value = rand() < 0.1 ? (rand() < 0.5 ? 0 : top) : Math.floor(rand() * (top + 1));
      if (!used.has(value)) { used.add(value); return value; }
    }
  };
  const arr = [];
  const specialValue = fresh();
  for (let i = 0; i < special; i++) arr.push(specialValue);
  let rest = n - special;
  while (rest > 0) {
    const count = Math.min(rest, 1 + Math.floor(rand() * quarter));
    const value = fresh();
    for (let i = 0; i < count; i++) arr.push(value);
    rest -= count;
  }
  arr.sort((a, b) => a - b);
  return [arr];
}
